Context: primary fix: a refusal from one peer no longer aborts the join
```
// Before:
                Ok(GardenResponse::Refused(reason)) => {
                    return Err(format!("a Garden validator refused the invite: {reason}"));
                }
// After:
                Ok(GardenResponse::Refused(reason)) => {
                    // A refusal is one peer's answer, not the Garden's: a
                    // member can withhold admission on purpose, and "no room
                    // for more peers" is transient. Remember it and keep
                    // waiting for a validator that admits this node.
                    refusals.insert(peer, reason);
